We will now combine API testing, deterministic LLM simulation, response validation, network mocking and retry testing into a single local application.

## 15.1 Architecture

## 15.2 Create the backend

Install:

```bash
pip install fastapi uvicorn pytest-playwright
```

Create `app.py`:

```python
from fastapi import FastAPI
from fastapi.responses import HTMLResponse
from pydantic import BaseModel, Field

app = FastAPI()

class ChatInput(BaseModel):

    question: str = Field(

        min_length=1,

        max_length=2000
    )

class Citation(BaseModel):

    document_id: str

    title: str

class ChatOutput(BaseModel):

    answer: str

    citations: list[Citation]

    total_tokens: int = Field(ge=0)

@app.get("/health")
def health():

    return {"status": "healthy"}

@app.post("/api/chat", response_model=ChatOutput)
async def chat(payload: ChatInput):

    return ChatOutput(

        answer="RAG combines retrieval and generation.",

        citations=[

            Citation(

                document_id="doc-101",

                title="RAG Guide"
            )
        ],

        total_tokens=120
    )
```

This endpoint is intentionally stateless and deterministic. It does not execute real LLM generation, retrieval or agent actions.

## 15.3 Create a frontend with bounded retries

Append the following route to `app.py`:

```python
@app.get("/", response_class=HTMLResponse)
def home():

    return """
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <title>AI Resilience Lab</title>
    </head>

    <body>

        <h1>AI Chatbot</h1>

        <form id="chat-form">

            <label for="question">Question</label>

            <input id="question" required>

            <button type="submit">Send</button>

        </form>

        <p data-testid="generation-status">Idle</p>

        <p data-testid="answer"></p>

        <p data-testid="error"></p>

        <script>

            const form = document.querySelector(
                "#chat-form"
            );

            const send = form.querySelector("button");

            const status = document.querySelector(
                '[data-testid="generation-status"]'
            );

            const answer = document.querySelector(
                '[data-testid="answer"]'
            );

            const errorBox = document.querySelector(
                '[data-testid="error"]'
            );

            const sleep = ms =>

                new Promise(resolve =>
                    setTimeout(resolve, ms)
                );

            async function ask(question) {

                const maxAttempts = 3;

                for (
                    let attempt = 0;
                    attempt < maxAttempts;
                    attempt++
                ) {

                    const response = await fetch(
                        "/api/chat",
                        {
                            method: "POST",

                            headers: {

                                "Content-Type":
                                    "application/json"
                            },

                            body: JSON.stringify({
                                question
                            }),

                            signal: AbortSignal.timeout(3000)
                        }
                    );

                    if (response.ok) {

                        const data = await response.json();

                        if (
                            typeof data.answer !== "string"
                            || !data.answer.trim()
                        ) {

                            throw new Error(
                                "Invalid AI response"
                            );
                        }

                        return data;
                    }

                    const retryable = [

                        429, 502, 503, 504

                    ].includes(response.status);

                    if (
                        !retryable
                        || attempt === maxAttempts - 1
                    ) {

                        throw new Error(
                            `Request failed: ${response.status}`
                        );
                    }

                    status.textContent = "Retrying";

                    const backoff = 200 * (2 ** attempt);

                    const retryAfter =
                        response.headers.get("Retry-After");

                    let serverDelay = 0;

                    if (
                        retryAfter
                        && /^\\d+$/.test(retryAfter)
                    ) {

                        serverDelay =
                            Number(retryAfter) * 1000;

                    } else if (retryAfter) {

                        serverDelay = Math.max(

                            0,

                            Date.parse(retryAfter)
                                - Date.now()
                        ) || 0;
                    }

                    const delay = Math.max(

                        backoff,

                        serverDelay
                    );

                    if (delay > 3000) {

                        throw new Error(
                            "Retry delay exceeds lab policy"
                        );
                    }

                    await sleep(delay);

                    status.textContent = "Generating";
                }
            }

            form.addEventListener(
                "submit",
                async event => {

                    event.preventDefault();

                    if (send.disabled) return;

                    send.disabled = true;

                    answer.textContent = "";

                    errorBox.textContent = "";

                    status.textContent = "Generating";

                    try {

                        const question =
                            document.querySelector(
                                "#question"
                            ).value;

                        const result = await ask(
                            question
                        );

                        answer.textContent =
                            result.answer;

                        status.textContent =
                            "Completed";

                    } catch (error) {

                        errorBox.textContent =
                            error.message;

                        status.textContent =
                            "Failed";

                    } finally {

                        send.disabled = false;
                    }
                }
            );

        </script>

    </body>
    </html>
    """
```

The frontend allows a maximum of three attempts for selected transient HTTP failures. It also recognizes `Retry-After`, applies per-attempt timeouts and restores the Send button on success or failure.

**Important design limitation:** We allow POST retries in this lab because the mocked chat operation is stateless. A real chat API may persist messages, charge for generation or trigger agent tools. Such operations need appropriate idempotency protection or reconciliation.

The example also intentionally does not retry network exceptions, implement jitter or enforce a single shared overall deadline. Those are separate policies that a production implementation should address.

## 15.4 Start the application

```bash
python -m uvicorn app:app --port 8000
```

For Python tests:

```bash
python -m playwright install chromium
```

For TypeScript tests:

```bash
npm install -D @playwright/test
npm install zod
npx playwright install chromium
```

**What this code covers**


**Defines:** `submit_question()`, `assert_controls_recovered()`, `test_success()`, `test_retry_after_503()`, `test_retry_exhaustion()`, `test_401_not_retried()`, `test_network_failure()`, `test_invalid_ai_response()`, `Citation`, `ChatResponse`

Create `tests/test_resilience.py`:

```python
from playwright.sync_api import Page, expect

BASE_URL = "http://127.0.0.1:8000"

MOCK_RESPONSE = {

    "answer": "Controlled RAG answer",

    "citations": [

        {
            "document_id": "doc-101",

            "title": "RAG Guide"
        }
    ],

    "total_tokens": 100
}

def submit_question(page: Page):

    page.goto(BASE_URL)

    page.get_by_label("Question").fill(
        "What is RAG?"
    )

    page.get_by_role(
        "button",
        name="Send"
    ).click()

def assert_controls_recovered(page: Page):

    expect(

        page.get_by_role(
            "button",
            name="Send"
        )

    ).to_be_enabled()

def test_success(page: Page):

    page.route(

        "**/api/chat",

        lambda route: route.fulfill(
            json=MOCK_RESPONSE
        )
    )

    submit_question(page)

    expect(

        page.get_by_test_id(
            "generation-status"
        )

    ).to_have_text("Completed")

    expect(

        page.get_by_test_id("answer")

    ).to_have_text("Controlled RAG answer")

    assert_controls_recovered(page)

def test_retry_after_503(page: Page):

    attempts = 0

    def handle_route(route):

        nonlocal attempts

        attempts += 1

        if attempts == 1:

            route.fulfill(

                status=503,

                json={"detail": "Unavailable"}
            )

        else:

            route.fulfill(

                status=200,

                json=MOCK_RESPONSE
            )

    page.route("**/api/chat", handle_route)

    submit_question(page)

    expect(

        page.get_by_test_id(
            "generation-status"
        )

    ).to_have_text("Completed")

    assert attempts == 2

    assert_controls_recovered(page)

def test_retry_exhaustion(page: Page):

    attempts = 0

    def handle_route(route):

        nonlocal attempts

        attempts += 1

        route.fulfill(

            status=503,

            json={"detail": "Unavailable"}
        )

    page.route("**/api/chat", handle_route)

    submit_question(page)

    expect(

        page.get_by_test_id(
            "generation-status"
        )

    ).to_have_text("Failed")

    assert attempts == 3

    assert_controls_recovered(page)

def test_401_not_retried(page: Page):

    attempts = 0

    def handle_route(route):

        nonlocal attempts

        attempts += 1

        route.fulfill(

            status=401,

            json={"detail": "Unauthorized"}
        )

    page.route("**/api/chat", handle_route)

    submit_question(page)

    expect(

        page.get_by_test_id(
            "generation-status"
        )

    ).to_have_text("Failed")

    assert attempts == 1

    assert_controls_recovered(page)

def test_network_failure(page: Page):

    page.route(

        "**/api/chat",

        lambda route: route.abort("failed")
    )

    submit_question(page)

    expect(

        page.get_by_test_id(
            "generation-status"
        )

    ).to_have_text("Failed")

    assert_controls_recovered(page)

def test_invalid_ai_response(page: Page):

    page.route(

        "**/api/chat",

        lambda route: route.fulfill(

            status=200,

            json={"answer": None}
        )
    )

    submit_question(page)

    expect(

        page.get_by_test_id(
            "generation-status"
        )

    ).to_have_text("Failed")

    expect(

        page.get_by_test_id("error")

    ).to_have_text("Invalid AI response")

    assert_controls_recovered(page)
```

Run:

```bash
pytest tests/test_resilience.py -v --headed
```

## 16.1 Add direct API contract tests

Create `tests/test_api.py`:

```python
import pytest

from pydantic import BaseModel, Field

class Citation(BaseModel):

    document_id: str

    title: str

class ChatResponse(BaseModel):

    answer: str = Field(min_length=1)

    citations: list[Citation]

    total_tokens: int = Field(ge=0)

@pytest.fixture
def api_client(playwright):

    client = playwright.request.new_context(

        base_url="http://127.0.0.1:8000"
    )

    try:

        yield client

    finally:

        client.dispose()

def test_chat_api(api_client):

    response = api_client.post(

        "/api/chat",

        data={"question": "What is RAG?"}
    )

    assert response.status == 200

    data = ChatResponse.model_validate(
        response.json()
    )

    assert data.total_tokens == 120

    assert data.citations[0].document_id == "doc-101"

def test_invalid_question(api_client):

    response = api_client.post(

        "/api/chat",

        data={"question": ""}
    )

    assert response.status == 422
```

Run all tests:

```bash
python -m pytest tests/ -v
```

## 17.1 Configure Playwright Test

Create `playwright.config.ts`:

```typescript
import { defineConfig } from "@playwright/test";

export default defineConfig({

    testDir: "./tests",

    fullyParallel: true,

    workers: 2,

    timeout: 30000,

    expect: {

        timeout: 10000
    },

    use: {

        baseURL: "http://127.0.0.1:8000",

        serviceWorkers: "block",

        screenshot: "only-on-failure",

        trace: "retain-on-failure"
    }
});
```

The example assumes the FastAPI server is running separately.

## 17.2 Parameterized resilience tests

Create `tests/resilience.spec.ts`:

```typescript
import {
    test,
    expect,
    type Page
} from "@playwright/test";

const mockResponse = {

    answer: "Controlled RAG answer",

    citations: [

        {
            document_id: "doc-101",

            title: "RAG Guide"
        }
    ],

    total_tokens: 100
};

async function submitQuestion(
    page: Page
): Promise<void> {

    await page.goto("/");

    await page.getByLabel("Question")
        .fill("What is RAG?");

    await page.getByRole("button", {

        name: "Send"

    }).click();
}

const scenarios = [

    {
        name: "Successful response",

        statuses: [200],

        expectedAttempts: 1,

        expectedStatus: "Completed"
    },

    {
        name: "Recover after HTTP 503",

        statuses: [503, 200],

        expectedAttempts: 2,

        expectedStatus: "Completed"
    },

    {
        name: "Recover after HTTP 429",

        statuses: [429, 200],

        expectedAttempts: 2,

        expectedStatus: "Completed"
    },

    {
        name: "Exhaust retry budget",

        statuses: [503, 503, 503],

        expectedAttempts: 3,

        expectedStatus: "Failed"
    },

    {
        name: "Do not retry HTTP 401",

        statuses: [401],

        expectedAttempts: 1,

        expectedStatus: "Failed"
    },

    {
        name: "Do not retry HTTP 422",

        statuses: [422],

        expectedAttempts: 1,

        expectedStatus: "Failed"
    }
];

for (const scenario of scenarios) {

    test(scenario.name, async ({ page }) => {

        let attempts = 0;

        await page.route(
            "**/api/chat",
            async route => {

                const status = scenario.statuses[

                    Math.min(

                        attempts,

                        scenario.statuses.length - 1
                    )

                ]!;

                attempts++;

                await route.fulfill({

                    status,

                    headers: status === 429

                        ? { "retry-after": "1" }

                        : {},

                    json: status === 200

                        ? mockResponse

                        : { detail: "Simulated error" }
                });
            }
        );

        await submitQuestion(page);

        await expect(

            page.getByTestId(
                "generation-status"
            )

        ).toHaveText(
            scenario.expectedStatus
        );

        expect(attempts).toBe(
            scenario.expectedAttempts
        );

        await expect(

            page.getByRole("button", {

                name: "Send"
            })

        ).toBeEnabled();

        if (scenario.expectedStatus === "Completed") {

            await expect(

                page.getByTestId("answer")

            ).toHaveText(mockResponse.answer);
        }
    });
}
```

This design allows you to introduce new failure sequences without duplicating the entire test.

## 17.3 Network failure and invalid schema tests

Append:

```typescript
test("Handle network failure", async ({ page }) => {

    await page.route(

        "**/api/chat",

        route => route.abort("failed")
    );

    await submitQuestion(page);

    await expect(

        page.getByTestId("generation-status")

    ).toHaveText("Failed");

    await expect(

        page.getByRole("button", {

            name: "Send"
        })

    ).toBeEnabled();
});

test("Reject invalid AI response", async ({ page }) => {

    await page.route(

        "**/api/chat",

        route => route.fulfill({

            status: 200,

            json: { answer: null }
        })
    );

    await submitQuestion(page);

    await expect(

        page.getByTestId("generation-status")

    ).toHaveText("Failed");

    await expect(

        page.getByTestId("error")

    ).toHaveText("Invalid AI response");
});
```

## 17.4 Direct API testing with Zod

Create `tests/api.spec.ts`:

```typescript
import { test, expect } from "@playwright/test";
import { z } from "zod";

const ChatSchema = z.object({

    answer: z.string().min(1),

    citations: z.array(

        z.object({

            document_id: z.string(),

            title: z.string()
        })
    ),

    total_tokens: z.number().int().nonnegative()
});

test("Verify actual FastAPI contract", async ({ request }) => {

    const response = await request.post(

        "/api/chat",

        {
            data: {

                question: "What is RAG?"
            }
        }
    );

    expect(response.status()).toBe(200);

    const result = ChatSchema.parse(
        await response.json()
    );

    expect(result.total_tokens).toBe(120);

    expect(result.citations).toContainEqual({

        document_id: "doc-101",

        title: "RAG Guide"
    });
});

test("Reject invalid API input", async ({ request }) => {

    const response = await request.post(

        "/api/chat",

        {
            data: {

                question: ""
            }
        }
    );

    expect(response.status()).toBe(422);
});
```

Run:

```bash
npx playwright test
```

Debug:

```bash
npx playwright test --debug
```

